SELECT u.unit_id FROM lctx_serving.retrieval_units u WHERE u.generation_digest=$1 AND u.family=ANY($2) AND ($3::text IS NULL OR EXISTS(SELECT 1 FROM lctx_serving.catalog_scenarios s WHERE s.generation_digest=$1 AND encode(s.scenario_id,'hex')=u.detail::jsonb->>'source_key' AND s.detail::jsonb->>'intent'=$3)) AND ($4::bytea IS NULL OR EXISTS(SELECT 1 FROM lctx_serving.retrieval_subjects s WHERE s.generation_digest=$1 AND s.unit_id=u.unit_id AND s.member_id=$4)) AND ($5::bytea IS NULL OR EXISTS(SELECT 1 FROM lctx_serving.retrieval_subjects s WHERE s.generation_digest=$1 AND s.unit_id=u.unit_id AND s.release_id=$5)) ORDER BY u.unit_id LIMIT 200001
